package dev.gamersclt.batcaverna.nativeapp;
import android.content.*;
import android.app.*;
import android.os.*;
import org.json.*;
/** Foreground inbox polling; closed-app delivery requires configured FCM server. */
final class NativeAlerts {
 private final MainActivity activity;private final Handler handler=new Handler();private boolean active,busy;private final Runnable tick=new Runnable(){public void run(){if(!active)return;poll();handler.postDelayed(this,20000);}};
 NativeAlerts(MainActivity a){activity=a;}
 void foreground(boolean value){active=value;handler.removeCallbacks(tick);if(value)tick.run();}
 private void poll(){SharedPreferences prefs=activity.getSharedPreferences("batcaverna",0);if(busy||!prefs.getBoolean("authenticated",false)||!prefs.getBoolean("native_alerts",false))return;busy=true;String user=prefs.getString("user_id","");new AccountRepository(activity).social(true,0,(rows,error)->{busy=false;if(!active||error!=null||!user.equals(prefs.getString("user_id","")))return;long cursor=prefs.getLong("alerts_cursor",0),next=cursor;for(int i=rows.length()-1;i>=0;i--){JSONObject row=rows.optJSONObject(i);long time=MessageTime.epoch(row.optString("created_at"));next=Math.max(next,time);if(cursor>0&&time>=cursor&&!row.optBoolean("read"))show(activity,row.optString("id"),row.optString("mensagem","Nova atividade na BatCaverna"));}prefs.edit().putLong("alerts_cursor",next).apply();});}
 static synchronized void show(Context c,String id,String message){if(!NotificationPolicy.shouldShow(message))return;SharedPreferences prefs=c.getSharedPreferences("batcaverna",0);if(!prefs.getBoolean("authenticated",false)||!prefs.getBoolean("native_alerts",false))return;if(Build.VERSION.SDK_INT>=33&&c.checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=android.content.pm.PackageManager.PERMISSION_GRANTED)return;NotificationManager manager=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);if(Build.VERSION.SDK_INT>=26)manager.createNotificationChannel(new NotificationChannel("community","Mensagens e atividades",NotificationManager.IMPORTANCE_DEFAULT));java.util.Set<String> seen=new java.util.LinkedHashSet<>(prefs.getStringSet("native_notified_ids",new java.util.HashSet<>()));if(!seen.add(id))return;while(seen.size()>128)seen.remove(seen.iterator().next());prefs.edit().putStringSet("native_notified_ids",seen).apply();Intent open=new Intent(c,MainActivity.class).setData(new android.net.Uri.Builder().scheme("batcaverna").authority("notification").appendPath(prefs.getString("user_id","")).appendPath(id).build()).putExtra("notification_id",id).putExtra("notification_user",prefs.getString("user_id","")).addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_SINGLE_TOP);PendingIntent action=PendingIntent.getActivity(c,0,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(c,"community"):new Notification.Builder(c);b.setLargeIcon(android.graphics.BitmapFactory.decodeResource(c.getResources(),R.drawable.app_logo)).setSmallIcon(R.drawable.ic_notification).setContentTitle("BatCaverna dos CLTs").setContentText(message).setStyle(new Notification.BigTextStyle().bigText(message)).setContentIntent(action).setAutoCancel(true);manager.notify(id.hashCode(),b.build());}
}
